    """
    The descriptor of a local or global agent, in its admitted JSON form; descriptors are authored in YAML.
    """

    model_config = ConfigDict(
        extra='forbid',
        populate_by_name=True,
    )
    descriptor_version: Annotated[
        str, Field(alias='descriptorVersion', pattern='^[0-9]+\\.[0-9]+$')
    ]
    """
    The version of the descriptor structure.
    """
    kind: Literal['LocalAgentDescriptor', 'GlobalAgentDescriptor']
    identity: Identity
    tuple: Tuple
    objectives: list[Objective] | None = None
    scope: AgentScope
    action_space: Annotated[list[ActionSpec] | None, Field(alias='actionSpace')] = None
    functions: Functions | None = None
    interfaces: Interfaces | None = None
    operations: Operations
    deployment: Deployment | None = None
    policies: Policies
    failure_policy: Annotated[FailurePolicy, Field(alias='failurePolicy')]
    model_hooks: Annotated[list[ModelHook] | None, Field(alias='modelHooks')] = None
    service_tree: Annotated[ServiceTree | None, Field(alias='serviceTree')] = None
    ownership: Ownership | None = None
    integrity: Integrity | None = None
